"""Deterministic static NBA research desk; no invented market observations."""
from pathlib import Path
from html import escape as e
import importlib.util
import json
ROOT=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('sample',ROOT.parent/'nba-2026-lab/compute.py')
sample=importlib.util.module_from_spec(spec); spec.loader.exec_module(sample)
LOG='https://www.nba.com/stats/player/1630162/boxscores?Season=2025-26'
INJ='https://official.nba.com/nba-injury-report-2026-27-season/'
GLOSS='https://www.nba.com/stats/help/glossary'
NAV=[('index.html','Overview'),('data.html','Evidence'),('strategies.html','Strategies'),('lines.html','Own lines'),('correlations.html','Correlations'),('gates.html','Validation'),('leaderboard.html','Leaderboard'),('review.html','Flagged for Review')]

def table(headers, rows):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers+['Official source / input context'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>' for v in cells)+'<td><a href="'+e(url,quote=True)+'">'+('NBA injury report' if url==INJ else 'NBA glossary' if url==GLOSS else 'NBA game / log')+'</a></td></tr>' for cells,url in rows)+'</tbody></table></div>'

def build():
    rows=sample.load()
    strategies=[
      ('S01','Single · spread','Opponent-adjusted strength + rest','Rolling game-level model; compare against simple home baseline',LOG),
      ('S02','Single · total','Pace and efficiency','Joint score distribution; evaluate totals calibration',GLOSS),
      ('S03','Single · player points','Minutes and role changes','Minutes distribution × conditional scoring model; freeze injury snapshot',INJ),
      ('S04','Cross-game parlay','Joint value after actual payout','Test residual dependence; never assume independence by default',LOG),
      ('S05','Same-game parlay','Game script and shared possessions','Joint simulations; bookmaker-specific void/settlement handling',LOG),
      ('S06','Player prop combo','Points, rebounds and assists dependence','Multivariate outcomes and threshold-specific joint hits',LOG)]
    gates=[
      ('G01','Provenance','Official input records, stable IDs, complete field-level review','Partial: only ten historical games rechecked'),
      ('G02','As-of integrity','Archive publication/collection/tip-off times; all features precede decision','Blocked: no timestamped feature ledger'),
      ('G03','Settlement','Record exact operator, jurisdiction, payout, pushes, voids and limits','Blocked: no reviewed NBA market ledger'),
      ('G04','Preregistration','Freeze strategy, feature set, variants, test family and power plan before holdout','Blocked: proposals only'),
      ('G05','Temporal holdout','Nested walk-forward tuning; group by game; untouched prospective final test','Blocked: no prospective predictions'),
      ('G06','Calibration','Compare Brier/log loss and reliability to frozen baseline by market','Blocked: no forecast ledger'),
      ('G07','Multiple testing','Holm correction for registered primary tests; log every attempted variant','Blocked: no completed tests'),
      ('G08','Net edge','Game/day-block bootstrap lower net-return bound above zero after costs','Blocked: no actual quoted payouts'),
      ('G09','Dependence / robustness','Test shared-leg exposure, regime shifts, ablations and leave-season-out stability','Blocked: only descriptive sample'),
      ('G10','Replication','Pass independent prospective period; drawdown and exposure limits fixed in advance','Blocked: no replication')]
    pages={}
    pages['index.html']=('NBA research, without invented edges', '''<p class="lead">An evidence-first workspace for originating lines, testing signals and rewarding repeatable performance—not lucky streaks.</p><div class="cards"><article><b>10</b><span>official game rows rechecked</span></article><article><b>6</b><span>candidate strategies</span></article><article><b>0</b><span>strategies certified</span></article><article><b>Research only</b><span>no live betting recommendations</span></article></div><h2>Executive summary</h2><p>The available NBA sample is valid for describing ten Anthony Edwards games, not for pricing today’s markets. Five correlations are reproducible; none proves an edge. Current lines, betting correlations, ROI and reward amounts remain blank where evidence is missing. Randomness cannot be removed from sport; uncertainty can be measured and false discoveries reduced.</p>'''+table(['Decision','Finding','Next requirement'],[
      (['Line origination','Do not publish actionable lines yet','Timestamped schedule, roster, injury and historical training inputs'],INJ),
      (['Correlation','Descriptive only; not threshold-specific bet dependence','Joint outcome ledger with actual prop thresholds'],LOG),
      (['Leaderboard','No rankings or awards yet','All validation gates plus independent replication'],LOG),
      (['Verification','Scoped evidence review, not blanket certification of legacy repository','See evidence and Flagged for Review'],LOG)])+'''<h2>Explore existing work</h2><p><a href="../nba-2026-lab/index.html">Historical NBA lab</a> · <a href="../nba-sensitivity/index.html">Leave-one-out sensitivity</a> · <a href="../docs/index.html">Earlier NBA site</a> · <a href="../index.html">Repository landing page</a></p><p><a href="../research/nba-validation/verification.md">Detailed verification record</a> · <a href="engine.py">Pricing and gate primitives</a> · <a href="report.json">Machine-readable research status</a></p>''')
    pages['data.html']=('Verified inputs', '<p>Checked against the season-filtered official NBA player log on 2026-11-03. All displayed fields below match. Minutes are as displayed by NBA (integer precision). This is the existing convenience-selected sample, not an exhaustive season dataset.</p>'+table(['Date','Game ID','Opponent','W/L','MIN','PTS','3PM','REB','AST'],[([r[k] for k in ('date','game_id','opponent','result','minutes','points','threes','rebounds','assists')],r['source']) for r in rows])+ '<h2>Official reporting and feature definitions</h2>'+table(['Item','Verified statement'],[
      (['Injury reporting','Generally 5 p.m. local time the day before; second back-to-back game by 1 p.m. local game day.'],INJ),
      (['Updates','Injury reports are updated continually throughout the day; no individual status is asserted here.'],INJ),
      (['%3PA','Percentage of team three-point field goals attempted by a player while on court.'],GLOSS),
      (['%AST','Percentage of team assists attributed to a player while on court.'],GLOSS)])+'<p><a href="../nba-2026-lab/data/edwards_2025_26_recent10.csv">Download reviewed source CSV</a></p>')
    pages['strategies.html']=('Candidate signal strategies','<p>These are project hypotheses, not proven effects or NBA recommendations. Source links support possible inputs only. Every candidate must clear every applicable gate.</p>'+table(['ID','Market','Proposed signal','Research design','Status'],[([i,m,s,d,'Pending validation'],u) for i,m,s,d,u in strategies]))
    pages['lines.html']=('Originate lines from distributions','<p>Proposed modeling architecture. No current game, sportsbook price or forecast is invented. The tested Python engine implements pricing arithmetic and gate aggregation, not a trained NBA forecast system.</p>'+table(['Stage','Proposed implementation','Available value'],[
      (['Ingest','Store official game IDs, team/player IDs, season, scheduled tip-off, source publication time, collection time and raw-file hash.',''],LOG),
      (['Team model','Fit regularized opponent-adjusted margin and joint score distributions using past-only data; model rest/home effects rather than assume constants.',''],LOG),
      (['Player model','Forecast minutes and usage conditional on as-of roster and injury information; integrate scenarios rather than substitute one guessed status.',''],INJ),
      (['Own threshold','Use median of forecast margin/total/stat draws; integer outcomes need explicit push mass.',''],LOG),
      (['Moneyline','From forecast p(win), fair decimal = 1 / p(win) where no push exists.',''],LOG),
      (['Expected return','Per unit stake: p(win) × decimal payout + p(push) − 1; payout includes returned stake.',''],LOG),
      (['Parlay pricing','Use joint outcome probabilities and actual offered combo payout; pairwise correlation alone does not price three or more legs.',''],LOG),
      (['Release','Publish only with reviewed evidence, uncertainty bounds and completed gates; otherwise no-bet.',''],INJ)])+'<p>All value cells intentionally blank: no current validated forecasts or executable quotes. Derived mathematical identities are not NBA-published odds.</p>')
    pages['correlations.html']=('Correlation is not an edge','<p>Pearson r, computed from the ten rechecked historical games. No causal or predictive inference. Points include points from three-pointers, so 3PM–PTS has a mechanical relationship. These are raw-stat associations, not correlations between priced bet outcomes.</p>'+table(['Variables','Pearson r','n','Interpretation'],[([x+' × '+y,f'{r:+.4f}',len(rows),'Exploratory only'],LOG) for x,y,r in sample.correlations(rows)])+'<h2>Bet-level dependencies</h2>'+table(['Measure','Value','Required evidence'],[
      (['Threshold-specific phi','','Paired binary hits under actual archived lines; zero-variance cases undefined'],LOG),
      (['Joint parlay hit probability','','All legs aligned by event and forecast time; handle voids/pushes separately'],LOG),
      (['Cross-game dependence','','Out-of-sample residuals clustered by game/day, not marginal stats'],LOG)])+'<h2>Pricing constraints</h2><p>For two binary events, max(0, pA+pB−1) ≤ pAB ≤ min(pA,pB). With nondegenerate marginals, pAB = pA·pB + phi·sqrt(pA(1−pA)pB(1−pB)). The engine rejects infeasible inputs. Do not substitute raw-stat Pearson r for binary phi. No independence assumption is certified here.</p><p><a href="../nba-sensitivity/index.html">Inspect all leave-one-game-out results</a></p>')
    pages['gates.html']=('Validation gates','<p>Proposed project policy, not an official NBA standard. Missing evidence blocks eligibility. Thresholds, power assumptions, bootstrap scheme and test family must be frozen before inspecting a final holdout. No universal sample size guarantees skill.</p>'+table(['Gate','Purpose','Pass requirement','Current status'],[(list(g),INJ if g[0]=='G02' else LOG) for g in gates])+'<h2>Separating evidence of skill from luck</h2><p>Retain every attempted strategy, including failures. Tune only inside chronological training windows; keep same-game legs together. Assess forecast quality against simple baselines before profitability. Correct the primary test family, preserve dependence when estimating uncertainty, and demand replication. Closing-line comparison is diagnostic, not proof of profit. Passing statistical tests cannot eliminate chance or guarantee future returns.</p>')
    pages['leaderboard.html']=('A competition with evidence gates','<p>Proposed reward policy: separate singles, cross-game parlays and same-game/player-combo tracks. Only fully eligible strategies enter rankings. Rank by a preregistered lower confidence bound of net return; use calibration and independent replication as tie-breaks. Lock common exposure limits and evaluation dates to prevent cherry-picking.</p>'+table(['Candidate','Track','Eligibility','Rank','ROI','Reward'],[([i,m,'Blocked','','',''],u) for i,m,s,d,u in strategies])+'<h2>Reward policy</h2><p>Awards remain unfunded and unset. No cash is promised. Release any future funded award only after independent ledger review and replication; withhold awards when no candidate passes. Prevent duplicate strategy submissions from evading multiple-testing correction. A real-money competition requires jurisdiction-specific legal and operator-rule review.</p>')
    flags=[('F01','Small selected sample','Only ten games from one player; no representative-sample or profit claim.',LOG),('F02','No executable odds','Current odds, spreads, totals, prop thresholds and CLV are unverified; values blank.',LOG),('F03','No prospective ledger','No holdout forecasts, calibrated edge, ROI or replication results.',LOG),('F04','Bet dependence missing','Raw-stat r cannot establish priced-leg phi; phi and joint hit estimates blank.',LOG),('F05','Roster/injury joins missing','Official reporting rules checked, individual statuses and decision-time joins not checked.',INJ),('F06','Rewards not funded','Reward amounts and ranks blank; proposed competition only.',LOG),('F07','Legacy audit boundary','Older NBA/NFL sites retained, not blanket re-certified; root is NFL-oriented.',LOG),('F08','Coordination history','Stale date/in-progress entries coexist with later publication records; no conflicting scope overwritten.',LOG),('F09','Source coverage','Official links support reviewed inputs, not endorsement of proposed strategies or methods.',GLOSS),('F10','Not a live forecasting service','Static Pages dashboard; no trained model, scheduled market feed, or wagering integration.',LOG)]
    pages['review.html']=('Flagged for Review','<p>These nonblocking research limitations remain visible after publication. Blank numerical cells mean unverified, not zero. Method proposals are explicitly labeled and are not official factual claims.</p>'+table(['ID','Issue','Disposition'],[([i,t,d],u) for i,t,d,u in flags]))
    for filename,(title,body) in pages.items():
        nav=''.join('<a '+('aria-current="page" ' if f==filename else '')+'href="'+f+'">'+label+'</a>' for f,label in NAV)
        (ROOT/filename).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Evidence-first NBA line origination and strategy validation research"><title>{e(title)} · Own5 NBA</title><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="index.html">OWN5 <span>/ NBA RESEARCH</span></a><span class="stamp">REVIEWED 03 NOV 2026</span></header><div class="layout"><nav aria-label="Main navigation">{nav}</nav><main id="main"><div class="eyebrow">EVIDENCE BEFORE EXECUTION</div><h1>{e(title)}</h1><aside class="notice">Research only · No validated betting edge · Missing values remain blank</aside>{body}<footer>Official facts · reproducible calculations · explicitly labeled proposals<br>Source links on proposal rows identify input context, not NBA endorsement. No gambling outcome is guaranteed.</footer></main></div></body></html>''')
    (ROOT/'report.json').write_text(json.dumps({'review_date':'2026-11-03','verified_game_rows':len(rows),'candidate_strategies':len(strategies),'certified_strategies':0,'current_lines':None,'bet_phi':None,'roi':None,'reward_amount':None,'correlations':[{'x':x,'y':y,'r':r,'n':len(rows),'source':LOG,'status':'descriptive_only'} for x,y,r in sample.correlations(rows)]},indent=2)+'\n')
if __name__=='__main__': build()
